sections.content:
// ❌ Не используйте для больших списков
ListView(
children: const [
ListTile(title: Text('Первый')),
ListTile(title: Text('Второй')),
ListTile(title: Text('Третий')),
],
)

// ✅ Используйте для маленьких списков
const ListView(
children: [
Text('Элемент 1'),
Text('Элемент 2'),
Text('Элемент 3'),
],
)

ListView.builder(
// Количество элементов
itemCount: items.length,
// Создание элемента
itemBuilder: (context, index) {
return ListTile(
title: Text(items[index]),
onTap: () {
print('Нажат элемент: ${items[index]}');
},
);
},
)

ListView.builder(
itemCount: items.length,
padding: const EdgeInsets.symmetric(vertical: 8),
// Направление прокрутки
scrollDirection: Axis.vertical, // или Axis.horizontal
// Физика прокрутки
physics: const BouncingScrollPhysics(),
// Кастомизация
itemBuilder: (context, index) {
final item = items[index];
return Card(
margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
child: ListTile(
leading: CircleAvatar(child: Text('${index + 1}')),
title: Text(item.title),
subtitle: Text(item.description),
trailing: Icon(Icons.chevron_right),
onTap: () => navigateToDetail(item),
),
);
},
)

ListView.separated(
itemCount: items.length,
separatorBuilder: (context, index) => const Divider(height: 1),
itemBuilder: (context, index) {
return ListTile(
title: Text(items[index]),
);
},
)

class ScrollableList extends StatefulWidget {
@override
_ScrollableListState createState() => _ScrollableListState();
}

class _ScrollableListState extends State<ScrollableList> {
final ScrollController _controller = ScrollController();

@override
void initState() {
super.initState();
// Слушатель прокрутки
_controller.addListener(() {
print('Позиция: ${_controller.position.pixels}');
});
}

@override
void dispose() {
_controller.dispose(); // Важно!
super.dispose();
}

@override
Widget build(BuildContext context) {
return Column(
children: [
ElevatedButton(
onPressed: () {
// Плавная прокрутка к началу
_controller.animateTo(
0,
duration: const Duration(milliseconds: 500),
curve: Curves.easeInOut,
);
},
child: const Text('Наверх'),
),
Expanded(
child: ListView.builder(
controller: _controller,
itemCount: 100,
itemBuilder: (context, index) {
return ListTile(title: Text('Элемент $index'));
},
),
),
],
);
}
}

GridView.builder(
gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
crossAxisCount: 3,
mainAxisSpacing: 8,
crossAxisSpacing: 8,
childAspectRatio: 0.75,
),
itemCount: images.length,
padding: const EdgeInsets.all(8),
itemBuilder: (context, index) {
return ClipRRect(
borderRadius: BorderRadius.circular(8),
child: Image.network(
images[index],
fit: BoxFit.cover,
),
);
},
)

// Максимальная ширина столбца
GridView.builder(
gridDelegate: SliverGridDelegateWithMaxCrossAxisExtent(
maxCrossAxisExtent: 200, // Максимальная ширина
mainAxisSpacing: 8,
crossAxisSpacing: 8,
childAspectRatio: 1,
),
itemCount: items.length,
itemBuilder: (context, index) {
return Card(child: Center(child: Text(items[index])));
},
)

// Фиксированное количество столбцов
const SliverGridDelegateWithFixedCrossAxisCount(
crossAxisCount: 4,      // 4 столбца
mainAxisSpacing: 10,    // Вертикальный отступ
crossAxisSpacing: 10,   // Горизонтальный отступ
childAspectRatio: 1,    // Соотношение сторон
)

CustomScrollView(
slivers: [
SliverAppBar(
pinned: true,
expandedHeight: 200,
flexibleSpace: FlexibleSpaceBar(
title: const Text('Список'),
),
),
SliverList(
delegate: SliverChildBuilderDelegate(
(context, index) {
return ListTile(title: Text('Элемент $index'));
},
childCount: 100,
),
),
],
)

CustomScrollView(
slivers: [
SliverGrid(
gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
crossAxisCount: 2,
mainAxisSpacing: 8,
crossAxisSpacing: 8,
),
delegate: SliverChildBuilderDelegate(
(context, index) {
return Container(
color: Colors.primaries[index % Colors.primaries.length],
);
},
childCount: 20,
),
),
],
)

ListView.builder(
itemBuilder: (context, index) {
return ListTile(
key: ValueKey(items[index].id),
title: Text(items[index].title),
);
},
)

Column(
children: [
const Text('Заголовок'),
Expanded(
child: ListView.builder(
itemCount: items.length,
itemBuilder: (context, index) {
return ListTile(title: Text(items[index]));
},
),
),
],
)
